let input = {};
try { input = $('When Executed by Orchestrator').item.json; } catch {}
if (!input.study_id) { try { input = $('Inject Test Payload').item.json; } catch {} }
if (!input.study_id) { try { input = $('Extract Webhook Body').item.json; } catch {} }
const studyRows = Array.isArray($input.first().json) ? $input.first().json : [$input.first().json];
const study = studyRows[0] ?? {};
const startedAt = study.started_at ? new Date(study.started_at) : new Date();
const durationSeconds = study.duration_seconds ?? input.duration_seconds ?? 600;
const studyEndTime = new Date(startedAt.getTime() + durationSeconds * 1000);
const inheritedEndTime = input.study_end_time ?? null;
const resolvedEndTime = inheritedEndTime ? new Date(inheritedEndTime) : studyEndTime;
const isFirstCycle = (input.last_etag_seen ?? null) === null;
const reviewMode = input.review_mode ?? study.metadata?.review_mode ?? false;
const studyId = study.study_id ?? input.study_id;
const studyStatus = study.status ?? 'running';
const cameraId = input.camera_id ?? 'camera_1';
const proxyUrl = 'http://127.0.0.1:5680?camera=' + cameraId;
const supabaseUrl = $env.SUPABASE_URL || 'https://SET_SUPABASE_URL';
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY || 'SET_SUPABASE_SERVICE_ROLE_KEY';
const headers = { 'apikey': supabaseKey, 'Authorization': 'Bearer ' + supabaseKey, 'Content-Type': 'application/json' };
const now = new Date();
if (studyStatus === 'analyzing' || studyStatus === 'complete') { return []; }
const BUFFER_MS = 10000;
if (!isFirstCycle && now > new Date(resolvedEndTime.getTime() + BUFFER_MS)) {
  try { await this.helpers.httpRequest({ method: 'PATCH', url: supabaseUrl + '/rest/v1/BE_studies?study_id=eq.' + encodeURIComponent(studyId), headers: { ...headers, 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: 'analyzing', current_stage: 'analyzing', updated_at: new Date().toISOString() }) }); } catch(e) {}
  try { await this.helpers.httpRequest({ method: 'POST', url: 'http://100.74.234.95:5678/webhook/agent-06-trigger', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ study_id: studyId, output_mode: 'final_insights' }) }); } catch(e) {
    try { await this.helpers.httpRequest({ method: 'POST', url: supabaseUrl + '/rest/v1/BE_insight_outputs', headers: { ...headers, 'Prefer': 'return=minimal' }, body: JSON.stringify({ study_id: studyId, output_mode: 'pending_retry', status: 'pending', dashboard_summary: 'Watchdog triggered — agent 06 needs to be run manually.', charts: [], tables: [], insights: ['Study completed but agent 06 was not triggered automatically.'], recommendations: [], created_at: new Date().toISOString() }) }); } catch(e2) {}
  }
  return [];
}
if (isFirstCycle) {
  try { await this.helpers.httpRequest({ method: 'PATCH', url: supabaseUrl + '/rest/v1/BE_studies?study_id=eq.' + encodeURIComponent(studyId), headers: { ...headers, 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: 'running', current_stage: 'monitoring', updated_at: new Date().toISOString() }) }); } catch(e) {}
}
let allDetections = [], recentDetections = [], studyContext = null;
try {
  // FIX: 9s timeout prevents indefinite hang that blocks the loop
  const allRes = await this.helpers.httpRequest({ method: 'GET', url: supabaseUrl + '/rest/v1/BE_behavior_detections?study_id=eq.' + encodeURIComponent(studyId) + '&order=timestamp.asc&limit=1000', headers, timeout: 9000 });
  allDetections = Array.isArray(allRes) ? allRes : [];
  recentDetections = allDetections.slice(-3).map(d => ({ timestamp: d.timestamp_pt ?? d.timestamp, detected_behaviors: d.detected_behaviors ?? [], notes: d.notes ?? '' }));
  if (allDetections.length > 0) {
    const behaviorStats = {};
    for (const d of allDetections) { for (const b of (d.detected_behaviors ?? [])) { if (!behaviorStats[b.name]) behaviorStats[b.name] = { values: [], unit: b.unit }; if (typeof b.value === 'number') behaviorStats[b.name].values.push(b.value); } }
    const behaviorSummary = {};
    for (const [name, stats] of Object.entries(behaviorStats)) {
      const vals = stats.values; if (vals.length === 0) continue;
      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
      const sorted = [...vals].sort((a, b) => a - b);
      let trend = 'stable';
      if (vals.length >= 6) { const earlyAvg = vals.slice(0, 3).reduce((a, b) => a + b, 0) / 3; const recentAvg = vals.slice(-3).reduce((a, b) => a + b, 0) / 3; if (recentAvg > earlyAvg + 0.5) trend = 'rising'; else if (recentAvg < earlyAvg - 0.5) trend = 'falling'; }
      const recentChanges = [];
      for (let i = Math.max(1, vals.length - 3); i < vals.length; i++) { const delta = vals[i] - vals[i - 1]; const ts = allDetections[i]?.timestamp_pt ?? allDetections[i]?.timestamp ?? ''; if (Math.abs(delta) >= 2) recentChanges.push((delta > 0 ? '+' : '') + delta.toFixed(0) + ' at ' + ts); }
      behaviorSummary[name] = { unit: stats.unit, detection_count: vals.length, mean: Math.round(mean * 10) / 10, min: sorted[0], max: sorted[sorted.length - 1], trend, recent_changes: recentChanges };
    }
    studyContext = { detection_count: allDetections.length, elapsed_seconds: Math.round((now - startedAt) / 1000), behaviors: behaviorSummary };
  }
} catch(e) { studyContext = null; recentDetections = []; }
return [{ json: { study_id: studyId, building_id: study.building_id ?? input.building_id ?? null, zone_ids: input.zone_ids ?? [], behavior_targets: input.behavior_targets ?? [], setup_instructions: input.setup_instructions ?? study.study_goal ?? '', proxy_url: proxyUrl, camera_id: cameraId, study_end_time: resolvedEndTime.toISOString(), last_etag_seen: input.last_etag_seen ?? null, review_mode: reviewMode, debug_mode: input.debug_mode ?? false, study_context: studyContext, recent_detections: recentDetections } }];

const ctx = $('Prepare Monitoring Context').item.json;
const etag = $json.etag ?? null;
const imageDataUrl = $json.image_data_url ?? null;
const lastEtagSeen = ctx.last_etag_seen ?? null;
const imageChanged = etag === null || etag !== lastEtagSeen;
const now = new Date();
const studyEndTime = new Date(ctx.study_end_time);
const studyExpired = now >= studyEndTime;
return [{ json: { ...ctx, image_data_url: imageDataUrl, current_etag: etag, image_changed: imageChanged, study_expired: studyExpired, checked_at: now.toISOString(), fetch_failed: imageDataUrl === null, image_id: 'snapshot_' + now.toISOString().replace(/[:.]/g, '-'), timestamp: now.toISOString(), zone_id: ctx.zone_ids?.[0] ?? null } }];

const ctx = $json;
const supabaseUrl = $env.SUPABASE_URL || 'https://SET_SUPABASE_URL';
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY || 'SET_SUPABASE_SERVICE_ROLE_KEY';
try { await this.helpers.httpRequest({ method: 'PATCH', url: supabaseUrl + '/rest/v1/BE_studies?study_id=eq.' + encodeURIComponent(ctx.study_id), headers: { 'apikey': supabaseKey, 'Authorization': 'Bearer ' + supabaseKey, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ status: 'analyzing', current_stage: 'analyzing', updated_at: new Date().toISOString() }) }); } catch(e) {}
return [{ json: ctx }];

const ctx = $json;
const dataUrl = ctx.image_data_url ?? '';
const imageId = ctx.image_id;
const cameraId = ctx.camera_id ?? 'camera_1';
const supabaseUrl = $env.SUPABASE_URL || 'https://SET_SUPABASE_URL';
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY || 'SET_SUPABASE_SERVICE_ROLE_KEY';
let mimeType = 'image/jpeg'; let base64Data = dataUrl; let fileExt = 'jpg';
if (dataUrl.startsWith('data:')) {
  const commaIdx = dataUrl.indexOf(','); const header = dataUrl.substring(5, commaIdx); base64Data = dataUrl.substring(commaIdx + 1);
  const mimeMatch = header.match(/^([^;]+)/);
  if (mimeMatch) { mimeType = mimeMatch[1].toLowerCase(); if (mimeType === 'image/png') fileExt = 'png'; else if (mimeType === 'image/webp') fileExt = 'webp'; else { mimeType = 'image/jpeg'; fileExt = 'jpg'; } }
}
base64Data = base64Data.replace(/\s/g, '');
const binaryBuffer = Buffer.from(base64Data, 'base64');
const magic = binaryBuffer.slice(0, 4);
if (magic[0] === 0xFF && magic[1] === 0xD8) { mimeType = 'image/jpeg'; fileExt = 'jpg'; }
else if (magic[0] === 0x89 && magic[1] === 0x50) { mimeType = 'image/png'; fileExt = 'png'; }
else if (magic[0] === 0x52 && magic[1] === 0x49) { mimeType = 'image/webp'; fileExt = 'webp'; }
const storagePath = `snapshots/${cameraId}/${imageId}.${fileExt}`;
const uploadUrl = supabaseUrl + '/storage/v1/object/camera-snapshots/' + storagePath + '?upsert=true';
const authHeader = 'Bearer ' + supabaseKey;
const fileName = imageId + '.' + fileExt;
const binaryData = await this.helpers.prepareBinaryData(binaryBuffer, fileName, mimeType);
return [{ json: { ...ctx, storage_path: storagePath, upload_url: uploadUrl, mime_type: mimeType, auth_header: authHeader, apikey: supabaseKey, buffer_size: binaryBuffer.length }, binary: { snapshot: binaryData } }];

const prev = $('Prepare Snapshot Binary').item.json;
const resp = $json;
const success = resp.Key !== undefined || resp.key !== undefined || resp.Id !== undefined || resp.id !== undefined;
return [{ json: { ...prev, snapshot_uploaded: success, snapshot_path: success ? prev.storage_path : null, snapshot_upload_error: success ? null : JSON.stringify(resp) }}];

const ctx = $('Check If Image Changed').item.json;
const body = $json;
let rawText = '';
if (body.output && Array.isArray(body.output)) { for (const block of body.output) { if (block.type === 'message' && Array.isArray(block.content)) { for (const c of block.content) { if (c.type === 'output_text' || c.type === 'text') { rawText = c.text ?? ''; break; } } } if (rawText) break; } }
if (!rawText && body.choices) rawText = body.choices?.[0]?.message?.content ?? '';
if (!rawText) rawText = body.output_text ?? '';
const debugResponse = { status: body.status ?? null, error: body.error ?? null, usage: body.usage ?? null, raw_text_extracted: rawText.slice(0, 500) };
let parsed = {}, parseError = null;
try { const clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim(); parsed = JSON.parse(clean); } catch (e) { parseError = 'parse_failed: ' + rawText.slice(0, 200); }
if (parseError && (!parsed.detected_behaviors || parsed.detected_behaviors.length === 0)) {
  return [{ json: { _skip_store: true, study_id: ctx.study_id, image_id: ctx.image_id, proxy_url: ctx.proxy_url, camera_id: ctx.camera_id, study_end_time: ctx.study_end_time, behavior_targets: ctx.behavior_targets, setup_instructions: ctx.setup_instructions, zone_ids: ctx.zone_ids, building_id: ctx.building_id, current_etag: ctx.current_etag, debug_mode: ctx.debug_mode, review_mode: ctx.review_mode, parse_error: parseError, raw_api_response: debugResponse } }];
}
const behaviorTargets = ctx.behavior_targets ?? [];
const normalizedBehaviors = (parsed.detected_behaviors ?? []).map((b, i) => { const target = behaviorTargets[i] ?? behaviorTargets[0]; return { name: target ? target.behavior_name : b.name, value: b.value, unit: target ? target.behavior_units : b.unit }; });
const finalBehaviors = normalizedBehaviors.length > 0 ? normalizedBehaviors : behaviorTargets.map(t => ({ name: t.behavior_name, value: 0, unit: t.behavior_units }));
let snapshotPath = null;
try { snapshotPath = $('Mark Snapshot Uploaded').item.json.snapshot_path ?? null; } catch {}
if (!snapshotPath) { try { snapshotPath = $('Skip Upload').item.json.snapshot_path ?? null; } catch {} }
return [{ json: { _skip_store: false, study_id: ctx.study_id, image_id: ctx.image_id, timestamp: ctx.timestamp, zone_id: ctx.zone_id, camera_id: ctx.camera_id, snapshot_path: snapshotPath, detected_behaviors: finalBehaviors, notes: parsed.notes ?? '', model_version: 'gpt-4.1', parse_error: parseError, raw_api_response: debugResponse, proxy_url: ctx.proxy_url, study_end_time: ctx.study_end_time, behavior_targets: ctx.behavior_targets, setup_instructions: ctx.setup_instructions, zone_ids: ctx.zone_ids, building_id: ctx.building_id, current_etag: ctx.current_etag, debug_mode: ctx.debug_mode, review_mode: ctx.review_mode } }];

let ctx = {};
try { ctx = $('Parse Detection JSON').item.json; } catch {}
if (!ctx.study_id) { try { ctx = $('Skip — Image Unchanged').item.json; } catch {} }
if (!ctx.study_id) { try { ctx = $('Check If Image Changed').item.json; } catch {} }
return [{ json: { study_id: ctx.study_id, building_id: ctx.building_id ?? null, zone_ids: ctx.zone_ids ?? [], behavior_targets: ctx.behavior_targets ?? [], setup_instructions: ctx.setup_instructions ?? '', proxy_url: ctx.proxy_url ?? 'http://127.0.0.1:5680?camera=camera_1', camera_id: ctx.camera_id ?? 'camera_1', study_end_time: ctx.study_end_time, last_etag_seen: ctx.current_etag ?? ctx.last_etag_seen ?? null, review_mode: ctx.review_mode ?? false, debug_mode: ctx.debug_mode ?? false } }];
